# ---------------- 399: Computer-Aided Drafting and Design I ----------------
H('399.d.1.A',3,"The letters CAD in drafting stand for:","computer-aided design",["central area drawing","copy and delete","color and depth"],"CAD means computer-aided design (or drafting).")
H('399.d.1.A',4,"Compared with hand drafting, a major advantage of CADD is that drawings can be:","edited, copied, and reused quickly",["only drawn once","never changed","printed only in one size"],"Digital drawings are easy to modify and reuse.")
H('399.d.1.B',3,"Before exiting CADD software, a drafter should first:","save the drawing",["unplug the computer","pull the power cord","delete the file"],"Saving prevents lost or corrupted work.")
H('399.d.1.B',4,"Turning off the computer while a drawing file is open can cause the file to become:","corrupted",["clearer","smaller always","encrypted by default"],"Improper shutdown can damage files.")
H('399.d.1.C',3,"A native AutoCAD drawing file commonly uses the extension:","DWG",["MP3","DOCX","JPG"],"DWG is the native drawing format.")
H('399.d.1.C',4,"A drawing exchange format that many CAD programs can open is:","DXF",["WAV","PPT","ZIP only"],"DXF is a widely supported exchange format.")
H('399.d.1.D',3,"To avoid losing work during a long drawing session, a drafter should:","save often",["save once at the end","never save","close without saving"],"Frequent saves protect progress.")
H('399.d.1.D',4,"Saving a drawing under a new name while keeping the original untouched uses the:","Save As command",["Erase command","Close without saving","Undo only"],"Save As creates a new file.")
H('399.d.1.E',3,"Before drawing a floor plan in feet and inches, a drafter sets the drawing:","units",["wallpaper","font only","password"],"Units define how measurements are entered and shown.")
H('399.d.1.E',4,"Drawing limits define the:","working area of the drawing",["file name","printer brand","screen color"],"Limits mark the drawing boundary.")
H('399.d.1.F',3,"In the Cartesian coordinate system, the point where the X and Y axes cross is called the:","origin",["limit","vertex only","snap"],"The origin is 0,0.")
H('399.d.1.F',4,"A point entered as 3,4 is located:","3 units along X and 4 units along Y from the origin",["4 units along X and 3 along Y","3 units from the screen edge","at the origin"],"Coordinates are given as X,Y.")
H('399.d.1.G',3,"The snap function forces the cursor to move in:","fixed increments",["random jumps","the opposite direction","a spiral"],"Snap restricts the cursor to set spacing.")
H('399.d.1.G',4,"The grid in CADD software is best described as:","a pattern of dots that helps you judge distance",["a drawn object","a layer name","a plotting setting only"],"Grid dots are visual references and are not plotted.")
H('399.d.1.H',3,"The command line in CADD software is used to:","type commands and respond to prompts",["store paper","hide the drawing","print layers only"],"The command line shows and accepts commands.")
H('399.d.1.H',4,"Dynamic input displays command prompts and values:","near the cursor",["on a printout","in the title block","only on the status bar"],"Dynamic input places tooltips at the cursor.")
H('399.d.2.A',3,"Which tool is used to draw a straight segment between two points?","line tool",["circle tool","spline tool","hatch tool"],"The line tool draws segments.")
H('399.d.2.A',4,"Entering a length and a direction angle to draw a line uses:","polar coordinates",["no coordinates","a color table","a printer driver"],"Polar input uses distance and angle.")
H('399.d.2.B',3,"To draw a circle, a drafter can specify the center point and the:","radius or diameter",["layer color only","paper size","file name"],"Circles need a center and size.")
H('399.d.2.B',4,"An ellipse differs from a circle because an ellipse has:","a major axis and a minor axis of different lengths",["a single radius","straight sides","no center"],"Ellipses have two axes.")
H('399.d.2.C',3,"A polyline is a connected sequence of segments that acts as:","a single object",["unrelated lines","a text block","a layer"],"A polyline is one object.")
H('399.d.2.C',4,"A donut with an inside diameter of zero is drawn as a:","filled circle",["square","line","spline"],"Zero inside diameter fills the ring.")
H('399.d.2.D',3,"A true spline curve is a smooth curve that passes through or near a set of:","control or fit points",["layer names","text styles","blocks"],"Splines are defined by points.")
H('399.d.2.D',4,"Splines are useful for drawing:","free-form curves such as a contour line",["straight walls only","text","title blocks"],"Splines model irregular curves.")
H('399.d.2.E',3,"A drawing template saves time because it stores settings such as units, layers, and the:","title block",["printer","password","operating system"],"Templates preload standard settings.")
H('399.d.2.E',4,"Drawing templates are usually saved with the extension:","DWT",["DWG","DXF","BAK"],"DWT is the template extension.")
H('399.d.2.F',3,"On a technical drawing, visible edges are shown with thick:","continuous lines",["dashed lines","dotted lines","center lines"],"Object lines are thick and continuous.")
H('399.d.2.F',4,"Hidden features behind a surface are shown with:","dashed lines",["thick solid lines","dimension lines","cutting-plane lines only"],"Hidden lines are dashed.")
H('399.d.2.G',3,"Layers in CADD are like transparent sheets used to organize:","drawing objects",["staff members","printers","file extensions"],"Layers group related objects.")
H('399.d.2.G',4,"Turning a layer off causes the objects on it to:","become invisible",["be deleted","change color permanently","move to another file"],"Off layers are hidden, not erased.")
H('399.d.2.H',3,"To keep dimensions separate from walls in a floor plan, put them on:","a different layer",["the same layer always","no layer","a printer"],"Separate layers aid control.")
H('399.d.2.H',4,"The layer that is currently active is the one on which:","new objects are drawn",["old objects are deleted","text is erased","plots are saved"],"New objects go on the current layer.")
H('399.d.2.I',3,"Before printing a drawing, a drafter should choose the printer and the:","paper size and plot scale",["font name only","file password","keyboard layout"],"Plot settings control output.")
H('399.d.2.I',4,"A plot preview is used to:","check how the sheet will look before printing",["delete the drawing","change the units","close the program"],"Preview avoids wasted prints.")
H('399.d.2.J',3,"Working in a planned order, such as drawing the outline before the details, shows good:","organizational skills",["luck","speed only","guessing"],"Sequencing the work improves efficiency.")
H('399.d.2.J',4,"Drawing the large basic shapes first and the small features last helps to:","reduce rework",["increase errors","hide layers","slow plotting"],"A planned sequence prevents redoing work.")
H('399.d.2.K',3,"A hexagon can be constructed in CADD with the:","polygon tool",["hatch tool","text tool","title tool"],"The polygon tool makes regular shapes.")
H('399.d.2.K',4,"A circle drawn tangent to two lines is constructed using the circle option called:","tangent, tangent, radius",["center, diameter only","three-point text","spline fit"],"TTR creates tangent circles.")
H('399.d.2.L',3,"Text on a drawing should have a style and a height that make it:","readable at the plotted scale",["tiny and faint","hidden","colored at random"],"Annotation must be legible.")
H('399.d.2.L',4,"Annotative or scaled text height at a scale of 1/4 inch per foot must be larger on screen so that it plots at:","the required printed height",["zero height","any random height","the screen height"],"Text height is scaled to plot correctly.")
H('399.d.2.M',3,"Object snap lets the cursor lock exactly onto a feature such as an:","endpoint or midpoint",["empty space","printer","menu color"],"Object snaps give precise positioning.")
H('399.d.2.M',4,"Ortho mode restricts cursor movement to:","horizontal and vertical directions",["curved paths","random angles","diagonals only"],"Ortho forces straight alignment.")
H('399.d.2.N',3,"The command used to remove an object from a drawing is:","erase",["plot","regen","save"],"Erase deletes objects.")
H('399.d.2.N',4,"The undo command is used to:","reverse the last action",["print the drawing","exit the program","rename a layer"],"Undo reverses commands.")
H('399.d.2.O',3,"Zooming in on a drawing changes the:","displayed view only, not the object size",["actual size of objects","drawing units","plot scale"],"Zoom changes the view.")
H('399.d.2.O',4,"Panning a drawing moves the view without changing:","the zoom level",["the screen","the mouse","the date"],"Pan shifts the view.")
H('399.d.2.P',3,"A layout (paper space) is used to arrange views for:","plotting on a sheet",["editing objects only","typing commands","saving layers"],"Layouts prepare sheets for plotting.")
H('399.d.2.P',4,"A drawing plotted at 1/4 inch = 1 foot means 1 inch on paper represents:","4 feet",["1 foot","12 inches","40 feet"],"1 / (1/4) = 4 feet per inch.")
H('399.d.2.Q',3,"The command that reports how far apart two picked points are is:","distance",["trim","extend","array"],"Query commands report data.")
H('399.d.2.Q',4,"The list command displays:","the properties of a selected object",["a plot","a file folder","printer ink"],"List shows object database information.")
H('399.d.2.R',3,"To shift an object to a new location without changing its size, use:","move",["scale","extend","stretch only"],"Move changes location.")
H('399.d.2.R',4,"The offset command creates:","a parallel copy at a set distance",["a rotated copy","a mirror copy","a deleted copy"],"Offset makes parallel objects.")
H('399.d.2.S',3,"The fillet command creates a rounded corner between two objects using a specified:","radius",["layer","font","plot scale"],"Fillet uses a radius.")
H('399.d.2.S',4,"A fillet radius of zero between two lines produces a:","sharp corner",["circle","spline","gap"],"Zero radius joins the lines at a corner.")
H('399.d.2.T',3,"Trim removes the part of an object that extends beyond a:","cutting edge",["layer","text","dimension"],"Trim cuts to boundaries.")
H('399.d.2.T',4,"The extend command lengthens an object until it meets a:","boundary edge",["viewport","title block","printer"],"Extend runs to a boundary.")
H('399.d.2.U',3,"The break command removes a portion of an object, leaving:","a gap",["a copy","a circle","a title"],"Break splits or removes a segment.")
H('399.d.2.U',4,"The join command combines collinear lines into:","one line",["one circle","a block","a dimension"],"Join merges objects.")
H('399.d.2.V',3,"The Properties palette can be used to change an object's color, layer, and:","linetype",["file name","printer brand","keyboard"],"Properties include linetype.")
H('399.d.2.V',4,"Changing an object's layer using the Properties palette also changes its:","assigned layer color and linetype by default",["position","size","units"],"ByLayer properties follow the layer.")
H('399.d.2.W',3,"Hatching is used to fill an enclosed area with a:","pattern",["voltage","units","file"],"Hatch patterns show material or section.")
H('399.d.2.W',4,"To calculate the area of a hatched region, a drafter can read the area from the hatch:","properties or the query area command",["layer name","text style","plot scale only"],"CADD can report enclosed area.")
H('399.d.3.A',3,"Multiple viewports in the drawing window let a drafter see:","several views of the model at the same time",["only one view","no views","the printer"],"Viewports show different areas or angles together.")
H('399.d.3.A',4,"Working in one viewport while another shows a zoomed-out view helps a drafter to:","keep track of detail and the whole drawing",["lose the layers","avoid zooming","hide the model"],"Multiple viewports combine overview and detail.")
H('399.d.3.B',3,"To start a line at the middle of a circle, use the object snap called:","center",["perpendicular","quadrant text","grid"],"Center snaps to the circle center.")
H('399.d.3.B',4,"To draw a line that meets another line at exactly 90 degrees, choose the object snap:","perpendicular",["endpoint","nearest","insert"],"Perpendicular snaps at right angles.")
H('399.d.3.C',3,"An orthographic drawing shows an object using several views such as the front, top, and:","right side",["inside only","price","color only"],"Orthographic projection uses principal views.")
H('399.d.3.C',4,"In an orthographic drawing, the top view is normally placed:","above the front view",["below the front view","beside the title","off the sheet"],"Standard view arrangement.")
H('399.d.3.D',3,"The first step in analyzing a design problem is to:","identify the constraints and requirements",["buy materials","start plotting","name the file"],"Understand the problem first.")
H('399.d.3.D',4,"A design that does not fit inside the available space has failed which type of requirement?","a size constraint",["a color preference","a title block rule","a font rule"],"Size limits are constraints.")
H('399.d.3.E',3,"In a site layout, scale and environmental features such as slope affect the placement of:","structures and drives",["font styles","line weights only","title blocks"],"Site conditions affect design.")
H('399.d.3.E',4,"Drawing a building so its large windows face the sun to gain heat is an example of using:","environmental features in design",["random placement","text styles","block libraries only"],"Orientation uses the environment.")
H('399.d.3.F',3,"A multi-view scaled drawing shows the object in views that are all drawn at the:","same scale unless noted",["different random scales","smallest scale","no scale"],"Views share a scale unless labeled.")
H('399.d.3.F',4,"If a view differs from the sheet's main scale, the drafter should:","label that view with its own scale",["hide the scale","delete the view","use red lines"],"Different scales must be noted.")
H('399.d.3.G',3,"The scale chosen for a drawing should allow the object to fit on the sheet and show:","enough detail to be understood",["no detail","only the title","only dimensions"],"Scale balances size and clarity.")
H('399.d.3.G',4,"A large building plan is commonly drawn at a scale such as:","1/4 inch = 1 foot",["1 inch = 1 inch","10 inches = 1 foot","full size"],"Architectural plans use reduced scales.")
H('399.d.3.H',3,"In an orthographic drawing, a horizontal flat surface appears as a line in the:","front view",["top view only","title block","scale bar"],"A horizontal surface is edge-on in the front view.")
H('399.d.3.H',4,"A vertical surface parallel to the front plane appears in its true shape in the:","front view",["top view","right side edge","section only"],"Surfaces parallel to a plane show true shape there.")
H('399.d.3.I',3,"A round hole in a surface that is parallel to the viewing plane appears as a:","circle",["line","square","spline"],"Parallel faces show true shape.")
H('399.d.3.I',4,"A circle on a surface that is perpendicular to the viewing plane appears as a:","line",["circle","ellipse only","dot"],"Edge-on circles look like lines.")
H('399.d.3.J',3,"A sectional view shows the inside of an object by imagining it:","cut open by a cutting plane",["painted","painted blue","turned off"],"Sections reveal internal features.")
H('399.d.3.J',4,"A conventional break is used on a drawing to shorten a view of a long part that has:","a uniform cross section",["a changing cross section","no length","hidden holes only"],"Breaks save space on uniform parts.")
H('399.d.3.K',3,"An assembly drawing shows how:","parts fit together",["a single part is made","the sheet is printed","layers are named"],"Assemblies show how parts relate.")
H('399.d.3.K',4,"Balloons with numbers on an assembly drawing refer to items in the:","parts list",["layer list","plot style","coordinate system"],"Balloons key to the parts list.")
H('399.d.3.L',3,"A detail drawing gives complete information about a:","single part",["whole building","print queue","layer set"],"Detail drawings describe one part.")
H('399.d.3.L',4,"A detail drawing must include the dimensions, material, and:","tolerances needed to make the part",["color of the drafter's pen","the plotter model","the user's name only"],"Details include data for manufacturing.")
H('399.d.3.M',3,"The title block of a technical drawing usually includes the drawing name, scale, date, and the:","drafter's name or initials",["weather","stock price","file size"],"Title blocks identify the drawing.")
H('399.d.3.M',4,"Different types of technical drawings, such as mechanical or architectural, use title blocks that:","follow the standard for that field",["are always blank","are identical","are never used"],"Fields have their own title block formats.")
H('399.d.4.A',3,"Standard lettering on a technical drawing is typically:","uppercase, single-stroke, and legible",["decorative script","tiny italic","handwriting only"],"Engineering lettering is simple and clear.")
H('399.d.4.A',4,"A common standard height for text on a plotted drawing is:","1/8 inch",["1 inch","1/64 inch","3 inches"],"1/8 inch is typical.")
H('399.d.4.B',3,"A drawing is plotted at 1/4 inch = 1 foot, a scale factor of 48. Text that should plot 1/8 inch high must be drawn:","6 inches high",["1/8 inch high","48 inches high","1/48 inch high"],"1/8 x 48 = 6 inches.")
H('399.d.4.B',4,"At a scale factor of 2 (half size), text that should plot 1/8 inch high should be created at:","1/4 inch",["1/16 inch","1/8 inch","2 inches"],"1/8 x 2 = 1/4.")
H('399.d.4.C',3,"A text style defines the font, height, and:","width factor and orientation",["layer order","plotting date","paper brand"],"Styles store text properties.")
H('399.d.4.C',4,"Using a clear, simple font for notes on a drawing improves its:","readability",["file size only","print speed only","unit setting"],"Clarity helps readers.")
H('399.d.4.D',3,"Multi-line text is best used for:","paragraphs and general notes",["single short labels only","dimension lines","hatches"],"MTEXT supports wrapped paragraphs.")
H('399.d.4.D',4,"Single-line text is most appropriate for a:","short label",["long paragraph","table","drawing template"],"Single-line text suits brief labels.")
H('399.d.4.E',3,"To change the words in a note already on a drawing, you can:","double-click the text to edit it",["erase the layer","change the units","re-plot the sheet"],"Text can be edited in place.")
H('399.d.4.E',4,"Editing the text style of existing notes will update:","all text that uses that style",["no text","only new layers","the title block only"],"Styles control linked text.")
H('399.d.4.F',3,"A table in CADD is useful for creating:","a parts list or schedule",["a spline","a viewport","a hatch pattern"],"Tables organize data.")
H('399.d.4.F',4,"A door schedule on a floor plan is typically made with a:","table",["circle","revision cloud","dimension"],"Schedules are tables.")
H('399.d.5.A',3,"A chamfer on a corner replaces the sharp edge with a:","angled cut",["rounded curve","hole","hatch"],"Chamfer is a bevel.")
H('399.d.5.A',4,"Unlike a fillet, a chamfer connects two lines with a:","straight segment",["curve","spline","dimension"],"Chamfers are straight; fillets are curved.")
H('399.d.5.B',3,"Editing tools in CADD allow a drafter to change existing drawings:","without redrawing from scratch",["only by erasing everything","by hand","only at plot time"],"Modify tools save time.")
H('399.d.5.B',4,"The stretch command changes the shape of an object by moving selected:","vertices or endpoints",["layers","units","colors"],"Stretch moves selected points.")
H('399.d.5.C',3,"The polyline edit command can join separate lines into:","one polyline",["one block","one layer","one viewport"],"PEDIT joins connected segments.")
H('399.d.5.C',4,"Spline edit lets a drafter adjust a curve by moving its:","fit or control points",["layers","fonts","file names"],"Splines are reshaped by points.")
H('399.d.5.D',3,"The copy command makes a duplicate of an object and:","leaves the original in place",["deletes the original","changes the layer","closes the file"],"Copy duplicates.")
H('399.d.5.D',4,"Using a base point when moving an object lets the drafter control exactly:","how far and where the object is displaced",["the plot scale","the layer color","the text height"],"Base point and second point define displacement.")
H('399.d.5.E',3,"The mirror command creates a reflected copy of an object across:","a mirror line",["a layer","a title block","a grid dot"],"Mirror needs an axis.")
H('399.d.5.E',4,"Drawing half of a symmetrical part and then mirroring it helps to:","save drawing time and ensure symmetry",["increase errors","remove a layer","slow plotting"],"Mirroring ensures exact symmetry.")
H('399.d.5.F',3,"If an object is scaled by a factor of 2, each of its lengths becomes:","twice as long",["half as long","unchanged","four times shorter"],"Scale factor multiplies lengths.")
H('399.d.5.F',4,"A rectangular array of 3 rows and 4 columns creates how many objects in all (including the original)?","12",["7","34","1"],"3 x 4 = 12.")
H('399.d.6.A',3,"Grips are small squares that appear on a selected object and allow quick:","editing such as stretching or moving",["printing","saving files","changing units"],"Grips give direct edit handles.")
H('399.d.6.A',4,"Selecting a grip and pressing the space bar cycles through edit modes such as stretch, move, rotate, scale, and:","mirror",["print","save","quit"],"Grip modes include mirror.")
H('399.d.6.B',3,"The Properties palette displays an object's layer, color, and:","dimensions or geometry",["author's address","phone number","file path"],"Properties show object data.")
H('399.d.6.B',4,"Quick Properties gives a short list of the most common:","properties for the selected object",["printer settings","fonts only","user names"],"Quick Properties is a compact version.")
H('399.d.6.C',3,"The Quick Select dialog box lets a drafter select objects by their:","property such as layer or type",["name only","owner","price"],"Filters choose matching objects.")
H('399.d.6.C',4,"Using Quick Select to choose all circles on a layer is faster than:","clicking each circle one at a time",["using the command line","opening a file","saving the drawing"],"Filtering reduces clicking.")
H('399.d.7.A',3,"A standard dimensioning rule is to place dimensions outside the object and avoid:","repeating the same dimension",["using numbers","using units","using arrows"],"Each feature is dimensioned once.")
H('399.d.7.A',4,"Dimension lines should not cross each other, and extension lines have a small gap from the:","object being dimensioned",["title block","sheet border","viewport"],"A visible gap separates extension lines from the part.")
H('399.d.7.B',3,"A drawing scale such as 1:2 means the drawing is:","half the actual size",["twice the actual size","full size","not to scale"],"1:2 is a reduction.")
H('399.d.7.B',4,"Dimension values on a scaled drawing must show the:","true size of the object",["size on paper","size on screen","scale of the printer"],"Dimensions report real measurements.")
H('399.d.7.C',3,"A dimension style controls the arrow size, text height, and the:","format of dimensions",["file name","printer driver","user name"],"Styles store dimension settings.")
H('399.d.7.C',4,"Changing a dimension style updates all dimensions that:","use that style",["are on other drawings","are erased","are in other files only"],"Styles are linked to dimensions.")
H('399.d.7.D',3,"A linear dimension measures the distance between two:","points along a horizontal or vertical direction",["colors","layers","text styles"],"Linear dimensions measure straight distance.")
H('399.d.7.D',4,"An angular dimension is used to measure the angle between:","two lines",["two layers","two text blocks","two files"],"Angular dimensions measure angles.")
H('399.d.7.E',3,"Chain dimensions are placed:","end to end in a line",["all from one baseline","in a circle","on top of each other"],"Chain dimensions run in sequence.")
H('399.d.7.E',4,"Datum (baseline) dimensions all measure from the same:","starting edge or point",["layer","color","scale"],"Baseline dimensioning avoids accumulated error.")
H('399.d.7.F',3,"On a drawing, the symbol placed before a circle's diameter value is:","a circle with a slash",["R","SQ","the letter D lowercase"],"The diameter symbol precedes the value.")
H('399.d.7.F',4,"A dimension for an arc usually gives its:","radius with an R",["diameter with a slash","area","volume"],"Arcs are dimensioned by radius.")
H('399.d.7.G',3,"The appearance of dimension text, such as its height, can be changed through the:","dimension style",["layer name","file name","print queue"],"Styles control appearance.")
H('399.d.7.G',4,"A dimension that shows a rounded value, such as 2.5 instead of 2.500, is set through the:","precision setting",["plot style","layer color","block name"],"Precision controls decimal places.")
H('399.d.7.H',3,"Equal spacing between stacked dimension lines makes a drawing:","neater and easier to read",["harder to print","less accurate","slower to open"],"Consistent spacing is a drafting standard.")
H('399.d.7.H',4,"A command that sets even spacing between parallel dimension lines is:","dimension space",["dimension erase","dimension style delete","plot preview"],"The DIMSPACE command evens spacing.")
H('399.d.8.A',3,"A block is a group of objects that is saved and treated as:","a single object",["many separate lines","a layer","a printer"],"Blocks group objects.")
H('399.d.8.A',4,"Making a block of a door symbol lets a drafter:","reuse it throughout the drawing",["use it only once","avoid layers","prevent editing"],"Blocks speed repeated use.")
H('399.d.8.B',3,"To place a copy of a block in a drawing, use the:","insert command",["erase command","purge command","plot command"],"Insert places blocks.")
H('399.d.8.B',4,"When inserting a block, the insertion point is where the block's:","base point attaches",["name prints","color changes","layer is deleted"],"The base point locates the block.")
H('399.d.8.C',3,"Editing a block definition updates:","all insertions of that block",["only the first copy","none of the copies","only the layer"],"Blocks update globally.")
H('399.d.8.C',4,"One benefit of using blocks for repeated symbols is that a single change can be:","made once and applied everywhere",["made only by hand","impossible","restricted to one use"],"Block redefinition is efficient.")
H('399.d.8.D',3,"A block saved as a separate drawing file for use in other drawings is created with the:","wblock (write block) command",["trim command","hatch command","zoom command"],"WBLOCK writes a block to a file.")
H('399.d.8.D',4,"An advantage of saving a block as its own file is that it can be:","used in many different drawings",["used in only one drawing","printed only","hidden permanently"],"External blocks are portable.")
H('399.d.8.E',3,"A symbol library is a collection of:","commonly used blocks",["printer settings","passwords","plot styles only"],"Libraries store reusable symbols.")
H('399.d.8.E',4,"A well-organized symbol library saves time because drafters can:","find and insert standard symbols quickly",["avoid using layers","draw every symbol again","ignore standards"],"Libraries speed up work.")
H('399.d.8.F',3,"The purge command removes unused items such as:","unreferenced blocks and layers",["all drawn lines","the title block","the current layer"],"Purge cleans the file.")
H('399.d.8.F',4,"Purging a drawing before sending it to a client helps to reduce its:","file size",["scale","accuracy","dimensions"],"Removing unused items shrinks the file.")
H('399.d.9.A',3,"A pattern development of a cylinder lays out the lateral surface as a:","rectangle",["triangle","sphere","cone"],"A cylinder unrolls into a rectangle.")
H('399.d.9.A',4,"The length of the rectangle in the development of a cylinder with a 2-inch diameter is about:","6.28 inches",["2 inches","12.56 inches","3.14 inches"],"Circumference = pi x d = 6.28.")
H('399.d.9.B',3,"A transition piece connects two openings of different:","shapes or sizes",["colors only","brand names","printers"],"For example, a square-to-round duct.")
H('399.d.9.B',4,"Developments of transition pieces are commonly found using a method of:","triangulation",["hatching","mirroring","extruding only"],"Surfaces are divided into triangles.")
H('399.d.9.C',3,"When two pipes intersect, the drawing must show the line of:","intersection",["extension","gradient","title"],"Intersection curves define the joint.")
H('399.d.9.C',4,"Drawings involving intersecting pieces are important in sheet metal work because they show how to:","cut and join the parts",["print the sheet","name the layers","rename files"],"Fabricators need cut patterns.")
H('399.d.10.A',3,"Looking at a design problem from the viewpoint of the user can help a designer to:","find new solutions",["avoid planning","stop designing","skip drawings"],"New perspectives reveal options.")
H('399.d.10.A',4,"Asking a client what they dislike about their present kitchen is a way to:","gain a new perspective on the design problem",["end the project","avoid drawings","shorten the plot"],"Client feedback reveals needs.")
H('399.d.10.B',3,"Creative problem solving in design often begins with:","brainstorming many ideas",["picking the first idea only","avoiding sketches","printing the drawing"],"Brainstorming expands options.")
H('399.d.10.B',4,"After brainstorming several layouts, the designer should evaluate them against the:","client's requirements and constraints",["day of the week","paper color","file extension"],"Evaluation uses criteria.")
H('399.d.10.C',3,"A site plan shows a building in relation to the:","property and its surroundings",["interior wall colors","wiring colors","kitchen cabinets only"],"Site plans show the lot context.")
H('399.d.10.C',4,"A site plan often includes property lines, setbacks, driveways, and a:","north arrow",["recipe","title of a song","phone book"],"North orientation is shown.")
H('399.d.10.D',3,"A floor plan is an overhead view of a building as if it were cut horizontally about:","four feet above the floor",["at ground level only","at the roof peak","below the foundation"],"Floor plan cuts are taken at window height.")
H('399.d.10.D',4,"Walls, doors, windows, and room names are all shown on a:","floor plan",["wall section","plot plan only","detail of a nail"],"Floor plans show layout.")
H('399.d.10.E',3,"An elevation drawing shows a building as viewed from the:","side, front, or back",["above only","inside the walls only","under the ground"],"Elevations are vertical views.")
H('399.d.10.E',4,"Exterior elevations typically show the building's materials and the:","heights of floors and roofs",["names of workers","price lists","tax records"],"Elevations show vertical dimensions.")
H('399.d.10.F',3,"A roof plan is an overhead view that shows the roof's:","shape, slope, and ridge lines",["interior doors","wall colors","plumbing"],"Roof plans show roof geometry.")
H('399.d.10.F',4,"A roof pitch of 6:12 means the roof rises 6 inches for every:","12 inches of horizontal run",["12 inches of height","6 feet of run","12 feet of width"],"Pitch is rise per 12 inches of run.")
H('399.d.10.G',3,"A door and window schedule lists each opening's:","size, type, and quantity",["owner","paint brand","job site address"],"Schedules summarize openings.")
H('399.d.10.G',4,"Doors and windows on a floor plan are linked to the schedule by:","marks or tags",["colors","fonts","line weights"],"Tags reference schedule entries.")
H('399.d.10.H',3,"A wall section is a vertical cut through a wall that shows its:","layers of construction",["floor plan layout","landscape","paint colors only"],"Wall sections show construction detail.")
H('399.d.10.H',4,"A wall section typically shows the footing, foundation, framing, and:","roof connection",["owner","carpet brand","parking lot"],"Sections run from footing to roof.")
H('399.d.10.I',3,"A plot plan is drawn to show the building's location on the:","lot with distances to the property lines",["interior walls","roof shingles","furniture"],"Plot plans locate the structure.")
H('399.d.10.I',4,"Building codes require setbacks, which are minimum distances between a building and the:","property lines",["trees only","neighbors' furniture","road signs"],"Setbacks are shown on plot plans.")
H('399.d.10.J',3,"An electrical plan uses symbols to show the locations of outlets, switches, and:","light fixtures",["sinks","carpets","staircases only"],"Electrical plans locate fixtures.")
H('399.d.10.J',4,"A reflected ceiling plan is drawn as if looking:","up at the ceiling",["down at the floor","at the roof from outside","through the walls sideways"],"The plan is mirrored to the ceiling.")
H('399.d.11.A',3,"In a mechanical assembly project, each part is first drawn as a:","separate detail drawing",["single pixel","title page","legend"],"Individual parts are drawn first.")
H('399.d.11.A',4,"Drawing parts at full size (1:1) in the model before reducing the scale on the layout helps ensure:","accurate dimensions",["slower plotting","larger files only","hidden layers"],"Full-scale modeling preserves accuracy.")
H('399.d.11.B',3,"A closed assembly drawing shows the parts:","fitted together in their working positions",["scattered apart","erased","in alphabetical order"],"Closed assemblies show the assembled product.")
H('399.d.11.B',4,"Parts in a closed assembly must have mating dimensions that:","fit together correctly",["differ widely","are unlabeled","are all identical"],"Mating features must fit.")
H('399.d.11.C',3,"An exploded assembly drawing shows the parts:","separated along assembly lines",["hidden","merged into one","erased"],"Exploded views show how parts fit.")
H('399.d.11.C',4,"A parts list on an assembly drawing includes each part's item number, name, quantity, and:","material",["owner's age","printer","weather"],"Parts lists identify each part.")

# ---------------- 400: Computer-Aided Drafting and Design II ----------------
H('400.d.1.A',3,"Absolute coordinates such as 5,3 are measured from the:","origin of the coordinate system",["last point drawn","screen corner","printer margin"],"Absolute values reference 0,0.")
H('400.d.1.A',4,"A relative coordinate entry of @4,0 draws a segment that is:","4 units long to the right of the last point",["4 units from the origin","4 units up from the origin","at an angle of 4 degrees"],"The @ symbol measures from the last point.")
H('400.d.1.B',3,"In modern CADD software, commands are grouped into tabs and panels on the:","ribbon",["keyboard","plotter","power supply"],"The ribbon organizes commands.")
H('400.d.1.B',4,"A drop-down menu in CADD software is opened by selecting a menu name such as File or:","Edit",["Plotter name","Wall","Voltage"],"Menu bars list command groups.")
H('400.d.1.C',3,"Typing the word LINE on the command line is an example of a:","type-in command",["pulldown menu pick","icon click","hot spot"],"Commands can be keyed in.")
H('400.d.1.C',4,"Clicking a small picture of a circle on a toolbar is using a(n):","icon",["type-in command","pulldown menu","script"],"Icons are toolbar buttons.")
H('400.d.1.D',3,"Which of these is a standard draw command?","rectangle",["trim","mirror","erase"],"Rectangle creates a new object.")
H('400.d.1.D',4,"The command that draws a smooth curved segment of a circle is:","arc",["line","hatch","offset"],"Arc draws part of a circle.")
H('400.d.1.E',3,"Which of these is a modifying command?","rotate",["line","circle","polygon"],"Rotate edits existing objects.")
H('400.d.1.E',4,"The command that lengthens or shortens objects to meet others is:","trim or extend",["text","spline","plot"],"Trim and extend modify objects.")
H('400.d.1.F',3,"Choosing Zoom Extents displays:","all objects in the drawing",["only the title block","only one layer","a blank screen"],"Zoom Extents fits the whole drawing.")
H('400.d.1.F',4,"Rotating the view of a 3D model with the orbit tool changes the:","viewing angle of the model",["actual geometry","units","layer names"],"Orbit changes only the view.")
H('400.d.1.G',3,"To change the arrowhead style on all dimensions, a drafter should modify the:","dimension style",["layer color","plot scale","block name"],"Styles control arrowheads.")
H('400.d.1.G',4,"A new dimension style can be created by starting from an existing one and:","modifying its settings and saving under a new name",["erasing all dimensions","changing the units of the file","closing the drawing"],"Styles can be copied and revised.")
H('400.d.2.A',3,"A pictorial sketch shows an object in a way that looks like a:","photograph of its three-dimensional form",["table of numbers","list of parts only","single line"],"Pictorials show depth.")
H('400.d.2.A',4,"A graphic description of a part that includes dimensions, notes, and views is called a:","technical drawing",["recipe","movie","brochure"],"Technical drawings describe parts graphically.")
H('400.d.2.B',3,"Making rough freehand sketches early in a design helps a designer to:","explore and communicate ideas quickly",["avoid thinking","avoid planning","delay the project"],"Sketching speeds idea generation.")
H('400.d.2.B',4,"Grid paper is useful for sketching because it helps keep lines straight and:","proportions consistent",["colors bright","text small","files light"],"Grid helps proportion.")
H('400.d.2.C',3,"A projection method that shows an object with all three principal axes at equal angles is:","isometric projection",["perspective projection","orthographic projection with one view","section projection"],"Isometric uses equal axis angles.")
H('400.d.2.C',4,"In orthographic projection, projectors from the object to the view are:","parallel to each other and perpendicular to the plane",["converging to a point","curved","random"],"Orthographic projectors are parallel.")
H('400.d.2.D',3,"When converting a hand sketch into an electronic drawing, a drafter should first establish the:","scale and overall dimensions",["file name only","color scheme only","plotter"],"Scale and sizes come first.")
H('400.d.2.D',4,"A drafter should clean up a scanned sketch by redrawing it with:","precise lines, correct layers, and dimensions",["freehand marks","colors only","smudges"],"Final drawings follow standards.")
H('400.d.3.A',3,"Before operating CADD software on a shared lab computer, a student should be sure to follow the lab's:","file naming and saving rules",["lunch menu","holiday schedule","weather alerts"],"Labs have saving procedures.")
H('400.d.3.A',4,"Keyboard shortcuts in CADD software can increase a drafter's:","speed and efficiency",["file size","error rate","screen size"],"Shortcuts save time.")
H('400.d.3.B',3,"To draw a closed shape with equal sides and angles, use the:","polygon command",["spline command","text command","hatch command"],"Polygon draws regular shapes.")
H('400.d.3.B',4,"The command for drawing a series of connected line and arc segments as one object is:","polyline",["mirror","array","trim"],"Polylines can include arcs.")
H('400.d.3.C',3,"The mirror command creates a reversed copy and offers the choice to:","keep or delete the original",["change the layers","erase the text","save the file"],"Mirror asks about the source.")
H('400.d.3.C',4,"The rotate command needs a base point and a:","rotation angle",["scale factor","layer name","file name"],"Rotate requires an angle.")
H('400.d.3.D',3,"A two-dimensional object has length and width, while a three-dimensional object also has:","depth or height",["color only","texture only","sound"],"3D adds a third dimension.")
H('400.d.3.D',4,"A solid box in CADD is defined by its length, width, and:","height",["layer","text style","plot style"],"Boxes are 3D primitives.")
H('400.d.3.E',3,"The extrude command can convert a closed 2D shape into a:","3D solid",["text block","hatch","dimension"],"Extrusion adds height.")
H('400.d.3.E',4,"Extruding a 2-inch square profile by 5 inches creates a solid whose volume is:","20 cubic inches",["10 cubic inches","7 cubic inches","25 cubic inches"],"2 x 2 x 5 = 20.")
H('400.d.3.F',3,"A 2D view such as a front elevation can be generated from a 3D model by:","creating a view or flattened projection",["erasing the model","adding text","changing units"],"CADD can generate 2D views.")
H('400.d.3.F',4,"Making 2D drawings from a 3D model ensures the views are consistent because they all come from:","the same model",["different sketches","random sources","the printer"],"One model, many views.")
H('400.d.3.G',3,"Text blocks in CADD are useful for adding:","notes and labels to a drawing",["power to a circuit","layers to a printer","units to a file"],"Text provides annotation.")
H('400.d.3.G',4,"A revision note used again and again can be saved as a reusable:","block",["layer","grid","hatch"],"Reusable text is saved as a block.")
H('400.d.3.H',3,"An external reference (xref) links another drawing file into the current drawing so that:","changes to the source file can update the view",["the source file is deleted","only text is shown","plotting is disabled"],"Xrefs stay linked to their source.")
H('400.d.3.H',4,"Architects use xrefs to place a base floor plan under other drawings such as:","electrical or plumbing plans",["spreadsheets","emails","music files"],"Shared base plans coordinate trades.")
H('400.d.3.I',3,"CADD programs can import files of other formats, such as:","DXF or PDF underlays",["music tracks","movie scripts","e-books"],"Common exchange formats.")
H('400.d.3.I',4,"When importing a drawing created in another program, check that the units and scale are:","the same as the current drawing",["blank","random","in a different language"],"Mismatched units distort geometry.")
H('400.d.3.J',3,"Before plotting, the drafter should confirm the plot area, scale, and the:","paper size",["file extension","mouse type","wallpaper"],"Plot settings control the output.")
H('400.d.3.J',4,"Plotting to a PDF file is useful because it allows a drawing to be:","shared without the CADD software",["edited by anyone with CADD","hidden","made smaller than the model"],"PDFs are viewable by anyone.")
H('400.d.3.K',3,"Attributes attached to blocks store:","text data such as part numbers",["layer colors","plotter names","screen sizes"],"Attributes hold information.")
H('400.d.3.K',4,"Data stored in block attributes can be exported to a spreadsheet as a:","bill of materials",["layer","title page","paper"],"Attribute extraction builds tables.")
H('400.d.4.A',3,"Text justification determines how text is aligned relative to its:","insertion point",["layer","plot scale","units"],"Justification options such as left, center, right.")
H('400.d.4.A',4,"Multi-line text differs from single-line text because it can wrap within a:","defined text box width",["layer name","dimension","block"],"Multi-line text uses a bounding box.")
H('400.d.4.B',3,"A multi-leader is a note with an arrow and a line pointing to a:","feature on the drawing",["different file","printer","layer name"],"Leaders connect notes to features.")
H('400.d.4.B',4,"One multi-leader can point to several features if the drafter adds extra:","leader lines",["layers","plot styles","units"],"Multi-leaders can have several leaders.")
H('400.d.4.C',3,"Editing a dimension's text so that it shows a tolerance is done with the dimension:","edit tools or properties",["print settings","zoom tool","layer manager"],"Dimensions are edited after creation.")
H('400.d.4.C',4,"If a dimension text is overridden by typing a number, the dimension will no longer:","update automatically with the geometry",["display","print","belong to a layer"],"Overrides break associativity.")
H('400.d.4.D',3,"To make all dimensions on a drawing use a smaller arrow, a drafter should change the:","dimension style",["layer lock","plot area","units"],"Styles govern all dimensions that use them.")
H('400.d.4.D',4,"Different dimension styles may be needed when one drawing contains both:","metric and inch dimensions",["layers and blocks","text and tables","two colors"],"Units may need separate styles.")
H('400.d.4.E',3,"Crosshatching on a section view represents the:","cut material",["hidden lines","dimension","title block"],"Hatch patterns show cut surfaces.")
H('400.d.4.E',4,"Different hatch patterns on an assembly section are used to show:","different materials or parts",["different layers","different scales","different units"],"Patterns distinguish materials.")
H('400.d.4.F',3,"Isolating an object temporarily hides:","all other objects",["the selected object only","the title block only","nothing"],"Isolate shows only selected items.")
H('400.d.4.F',4,"Hiding objects that clutter a view is helpful when a drafter needs to:","work on a specific part of a crowded drawing",["delete the drawing","change units","close the file"],"Hiding reduces visual clutter.")
H('400.d.4.G',3,"A window selection selects only the objects that are:","completely inside the window",["partly inside","outside the window","on other layers"],"Window requires full enclosure.")
H('400.d.4.G',4,"A crossing selection selects objects that are:","inside or touching the selection rectangle",["entirely outside","hidden only","dimension-only"],"Crossing selects touched objects.")
H('400.d.4.H',3,"A rectangular array copies an object into rows and:","columns",["layers","blocks","scales"],"Rectangular arrays use rows and columns.")
H('400.d.4.H',4,"A polar array of 6 equally spaced copies around a full circle places them how many degrees apart?","60",["30","90","6"],"360 / 6 = 60.")
H('400.d.4.I',3,"The reference option of the rotate command lets a drafter rotate an object to match an existing:","angle",["layer","scale","style"],"Reference rotation aligns to existing geometry.")
H('400.d.4.I',4,"An object currently at 30 degrees must end up at 90 degrees. Using a reference, it rotates:","60 degrees",["30 degrees","90 degrees","120 degrees"],"90 minus 30.")
H('400.d.4.J',3,"A balanced layout with consistent alignment on a drawing sheet shows good use of:","design and organizational principles",["random placement","hidden layers","blank space only"],"Order and balance help communication.")
H('400.d.4.J',4,"Using more line weight for important outlines and lighter weight for details creates:","visual hierarchy",["confusion","errors in scale","hidden lines"],"Hierarchy guides the reader.")
H('400.d.4.K',3,"Setting a layer's color, linetype, and lineweight means all objects on that layer will:","follow those properties by layer",["lose their shape","move","be deleted"],"ByLayer properties are controlled centrally.")
H('400.d.4.K',4,"Locking a layer prevents its objects from being:","accidentally edited",["viewed","plotted","counted"],"Locked layers are visible but protected.")
H('400.d.4.L',3,"Page setup stores the plotter, paper size, and plot:","scale and area",["fonts only","user passwords","file owners"],"Page setup saves plot settings.")
H('400.d.4.L',4,"Saving a named page setup helps a drafter to:","reuse the same plot settings on many layouts",["delete layers","skip checking","change units"],"Named setups save time.")
H('400.d.4.M',3,"Reusable content such as a bolt symbol can be stored as a:","block",["layer","grid","viewport only"],"Blocks make reusable symbols.")
H('400.d.4.M',4,"A tool palette can store blocks so that they can be:","dragged into a drawing quickly",["deleted automatically","hidden permanently","printed only"],"Palettes provide quick access.")
H('400.d.4.N',3,"The Standard Alphabet of Lines defines the line types used for:","object, hidden, center, and other lines on drawings",["music","email","tax forms"],"It standardizes line meaning.")
H('400.d.4.N',4,"Under the Alphabet of Lines, a center line is drawn with:","long and short dashes alternating",["thick solid line","dotted line","phantom only"],"Center lines use long-short dashes.")
H('400.d.4.O',3,"A gradient fill is an area filled with a smooth transition between:","two colors",["two layers","two units","two text styles"],"Gradients blend colors.")
H('400.d.4.O',4,"A solid fill is often used in a drawing to emphasize:","a cut or important area",["every line","the title block border","the units"],"Fills highlight areas.")
H('400.d.4.P',3,"The angle of a hatch pattern can be changed to avoid lines that are:","parallel to an adjacent object's edge",["on another layer","in the title block","longer"],"Angle changes improve clarity.")
H('400.d.4.P',4,"Increasing a hatch pattern's scale makes the pattern spacing:","wider",["tighter","darker only","invisible"],"Larger scale means wider spacing.")
H('400.d.5.A',3,"Translating a hand sketch into CADD begins with setting up the file with the correct:","units and layers",["wallpaper","colors only","printer name"],"Setup precedes drawing.")
H('400.d.5.A',4,"When a hand sketch has no exact dimensions, the drafter should:","confirm dimensions with the designer before drawing",["guess all sizes","skip the part","draw in color only"],"Clarify before drawing.")
H('400.d.5.B',3,"A projected mechanical drawing aligns the front, top, and side views using:","projection lines",["fonts","layer names","text styles"],"Views are aligned by projection.")
H('400.d.5.B',4,"The width of the top view must match the width of the front view because both views show the same:","dimension of the object",["color","layer","file size"],"Shared dimensions must agree.")
H('400.d.5.C',3,"Attaching a gear drawing as an external reference keeps the main drawing:","smaller and updated when the gear changes",["larger always","fixed forever","locked"],"Xrefs reduce file size and update links.")
H('400.d.5.C',4,"If an external reference file is moved to a different folder, the main drawing may show:","a missing reference warning",["a new layer","a title block","a larger plot"],"Path changes break references.")
H('400.d.5.D',3,"In a parametric model, changing a dimension value causes the model to:","update automatically",["become fixed","be deleted","lose its parts"],"Parametric designs follow parameters.")
H('400.d.5.D',4,"Constraints in a parametric sketch, such as tangent or parallel, ensure the model:","keeps its geometric relationships when edited",["loses its shape","has no dimensions","cannot be saved"],"Constraints preserve design intent.")
H('400.d.5.E',3,"An animated exploded assembly helps viewers understand:","the order in which parts go together",["the price of parts","the sheet size","the color palette"],"Animation shows assembly sequence.")
H('400.d.5.E',4,"In a complex assembly of hundreds of parts, organizing the parts into subassemblies makes the model easier to:","manage and edit",["print only","hide","delete"],"Subassemblies simplify structure.")
H('400.d.5.F',3,"A wireframe model represents an object using only its:","edges",["faces","volume","mass"],"Wireframes have edges only.")
H('400.d.5.F',4,"Of the three 3D model types, only a solid model contains information about the object's:","volume and mass properties",["colors","layers","scale"],"Solids carry mass properties.")
H('400.d.5.G',3,"A composite drawing is made by combining parts from several drawings into:","one drawing",["no drawing","several printers","a table"],"Composite drawings assemble sources.")
H('400.d.5.G',4,"Before combining drawings, the drafter should make sure the drawings use the same:","units and scale",["fonts only","owners","dates"],"Matching units prevent errors.")
H('400.d.5.H',3,"A drafter who can explain why a section view was chosen is showing the ability to:","justify drawing methods",["avoid standards","skip reviews","hide layers"],"Justification explains choices.")
H('400.d.5.H',4,"Using an auxiliary view for a slanted surface is justified because it shows that surface in its:","true size and shape",["smallest form","hidden form","thickest form"],"Auxiliary views show true size of inclined faces.")
H('400.d.5.I',3,"The lines, arcs, and circles drawn in a floor plan or a gear drawing are made on:","separate layers by object type",["a single color","a blank page","one block"],"Layering organizes objects.")
H('400.d.5.I',4,"Drawing a bolt circle with six holes starts by drawing a:","center circle and one hole, then arraying it",["spline","table","dimension"],"A polar array creates the pattern.")
H('400.d.5.J',3,"Notes in a title block are often placed using middle-center justification so that the text is:","centered in its box",["pushed out of the box","deleted","stretched"],"Justification aligns text in a space.")
H('400.d.5.J',4,"To make a general note wrap neatly inside a narrow column on a sheet, use:","multi-line text with a set width",["a leader","a hatch","a block attribute"],"MTEXT wraps by width.")
H('400.d.5.K',3,"A multi-leader placed on a part with a callout number helps readers locate an:","item in the parts list",["layer","plot style","file"],"Callouts tie to the list.")
H('400.d.5.K',4,"Aligning several multi-leaders so that their text lines up makes a mechanical assembly drawing look:","neat and professional",["wrong","incomplete","unscaled"],"Alignment tools improve appearance.")
H('400.d.5.L',3,"To add a tolerance of plus or minus 0.005 to an existing dimension, edit the dimension's:","tolerance setting in its style or properties",["layer lock","viewport","hatch"],"Tolerances are set in style or properties.")
H('400.d.5.L',4,"Overriding a single dimension in a drawing changes only that dimension, while editing the style changes:","all dimensions that use the style",["none","only the first","only the last"],"Style edits apply broadly.")
H('400.d.5.M',3,"Hiding the dimension layer temporarily lets a drafter inspect the:","geometry without clutter",["title block","plot style","file name"],"Hiding layers aids inspection.")
H('400.d.5.M',4,"Unisolating objects after working on one part restores:","the display of all hidden objects",["the deleted objects","the previous file","a blank screen"],"Unisolate returns the view.")
H('400.d.5.N',3,"The fence selection method selects objects that are:","crossed by a line drawn through them",["inside a window only","on other layers","hidden"],"A fence picks what it touches.")
H('400.d.5.N',4,"A selection set saved with a name or filter lets a drafter:","reselect the same group of objects later",["delete layers","print twice","close the file"],"Saved sets speed up repeated edits.")
H('400.d.5.O',3,"Using a consistent layout for the views, notes, and title block on every sheet shows the principle of:","organization and consistency",["randomness","clutter","contrast only"],"Consistency helps readers.")
H('400.d.5.O',4,"Leaving white space around views on a drawing sheet makes the sheet more:","readable",["crowded","confusing","costly"],"Space improves clarity.")
H('400.d.5.P',3,"Layer names such as DIM, HIDDEN, and CENTER help a team to:","find and control objects by purpose",["slow down","lose files","hide the title"],"Meaningful names help organization.")
H('400.d.5.P',4,"A layer standard shared by a design team ensures that drawings from different people:","look and behave consistently",["differ","fail to print","lose data"],"Standards promote consistency.")
H('400.d.5.Q',3,"The plot style table controls how colors on screen print as:","line weights and colors on paper",["file types","layer names","units"],"Plot styles map objects to output.")
H('400.d.5.Q',4,"A plot setup that plots only the window selected should be used when you want to print:","a portion of the drawing",["a different file","a blank sheet","the layers"],"Window plotting prints part of the drawing.")
H('400.d.5.R',3,"A full section view is created by passing a cutting plane through the:","entire object",["title block","printer","layer manager"],"Full sections cut completely through.")
H('400.d.5.R',4,"An auxiliary view is projected perpendicular to a(n):","inclined surface",["horizontal line only","text","title block"],"Auxiliary views show slanted faces in true size.")
H('400.d.6.A',3,"A schematic drawing shows a circuit using:","symbols and connecting lines",["floor plans","solid models","sections"],"Schematics use symbols.")
H('400.d.6.A',4,"A schematic differs from a wiring drawing because it shows how a circuit works rather than the:","physical routing of wires",["resistor values","power source","symbols"],"Schematics show function, not layout.")
H('400.d.6.B',3,"A printed circuit board assembly package typically includes a parts list and a drawing of where parts are:","placed on the board",["sold","stored","shipped"],"Assembly drawings locate components.")
H('400.d.6.B',4,"The silkscreen layer of a printed circuit board drawing is used to print:","reference designators and outlines on the board",["copper traces","drill holes","power"],"Silkscreen marks component labels.")
H('400.d.6.C',3,"A connection drawing shows how the external wires attach to a:","terminal or connector",["layer","plot","viewport"],"Connection drawings show terminations.")
H('400.d.6.C',4,"Terminal numbers on a connection drawing help a technician to:","connect each wire to the right point",["change the scale","measure voltage","plot faster"],"Numbers prevent miswiring.")
H('400.d.6.D',3,"An interconnection drawing shows the wiring between:","separate units or assemblies",["layers","fonts","plot styles"],"Interconnection links units.")
H('400.d.6.D',4,"On an interconnection drawing, cable designations tell the installer which cable runs between which:","units",["fonts","layers","scales"],"Designations identify cables.")
H('400.d.6.E',3,"A wiring drawing shows the path of wires and their:","color codes or numbers",["paint","prices","heights"],"Wires are identified by code.")
H('400.d.6.E',4,"A list accompanying a wiring drawing gives the 'from' and 'to' points of each:","wire",["layer","scale","font"],"Wire lists give endpoints.")
H('400.d.6.F',3,"A cable or harness drawing shows how wires are grouped and:","bundled, with lengths and connectors",["painted","priced","hidden"],"Harness drawings define assembly.")
H('400.d.6.F',4,"A harness board drawing is often made full size so that technicians can lay wires:","directly on the drawing",["in the trash","on the wall","in a drawer"],"Full-size boards guide assembly.")
H('400.d.6.G',3,"A component drawing of an electronic part gives its dimensions and its:","lead or pin locations",["price only","color only","owner"],"Component drawings locate pins.")
H('400.d.6.G',4,"A footprint drawing of a component used in circuit board design shows the:","pad pattern where the part is soldered",["circuit voltage","battery type","time"],"Footprints define pads.")
H('400.d.6.H',3,"A logic diagram uses symbols such as AND, OR, and NOT to show:","how signals are processed",["floor layouts","soil types","paint colors"],"Logic diagrams show gates.")
H('400.d.6.H',4,"An AND gate outputs a high signal only when:","all of its inputs are high",["one input is low","no input exists","any input is high"],"AND needs all inputs high.")
H('400.d.7.A',3,"A gear drawing includes data such as the number of teeth and the:","pitch diameter",["paint color","price","supplier"],"Gear data tables list teeth and pitch.")
H('400.d.7.A',4,"A spring drawing must give the wire diameter, the free length, and the:","number of coils",["owner","date only","scale of the sheet"],"Spring data defines the part.")
H('400.d.7.B',3,"A detail drawing provides all the information needed to make a single:","part",["building","assembly line","contract"],"Detail drawings describe one part.")
H('400.d.7.B',4,"In addition to the views and dimensions, a detail drawing includes the material and the:","tolerances",["supplier's address","owner's name","budget"],"Tolerances define acceptable variation.")
H('400.d.7.C',3,"A surface development is a drawing that shows a surface:","laid out flat",["rotated","hidden","colored"],"Developments flatten surfaces.")
H('400.d.7.C',4,"Sheet metal ductwork, such as a transition fitting, is made from a pattern created through:","surface development",["rendering","plotting","hatching"],"Developments produce patterns.")
H('400.d.7.D',3,"A weld symbol on a drawing tells the fabricator the type and the:","size of the weld",["owner","color","layer"],"Weld symbols carry size and type.")
H('400.d.7.D',4,"A weld symbol placed below the reference line indicates that the weld is on the:","arrow side of the joint",["other side","outside of the sheet","hidden side"],"Below the line is the arrow side.")
H('400.d.7.E',3,"A drawing of a bearing must include the bore diameter and the:","outside diameter",["customer","color","owner"],"Bearing drawings include the diameters.")
H('400.d.7.E',4,"The fit of a bearing on a shaft is controlled by giving the shaft and the bore:","tolerances",["colors","names","symbols only"],"Fits come from tolerances.")
H('400.d.7.F',3,"A casting drawing shows the shape of a part made by pouring metal into a:","mold",["pipe","press","frame"],"Casting uses molds.")
H('400.d.7.F',4,"Casting drawings include draft angles so that the pattern can be removed from the:","mold",["floor","press","drawer"],"Draft allows release.")
H('400.d.7.G',3,"A forging drawing shows the shape of a part made by shaping heated metal with:","compressive force",["paint","water","light"],"Forging uses force.")
H('400.d.7.G',4,"A forging drawing often shows the finished part outline inside the forging outline to show the amount of:","material machined away",["paint","labor","packing"],"The difference is stock for machining.")
H('400.d.7.H',3,"A tool drawing, such as a jig or fixture drawing, describes a device that helps to hold or guide a:","workpiece",["paint","owner","budget"],"Jigs and fixtures hold work.")
H('400.d.7.H',4,"A jig differs from a fixture because a jig also:","guides the cutting tool",["costs less","has no parts","is always smaller"],"Jigs guide tools.")
H('400.d.7.I',3,"A molding diagram for plastic parts shows the part shape, the parting line, and the:","gate location",["owner","price","color of paper"],"Gates feed plastic into the mold.")
H('400.d.7.I',4,"Uniform wall thickness in a molded plastic part helps to reduce:","warping and sink marks",["color","price","weight only"],"Uniform walls cool evenly.")
H('400.d.7.J',3,"A stamping drawing shows the shape of a part made by pressing sheet metal with a:","die",["brush","roller","saw"],"Stamping uses dies.")
H('400.d.7.J',4,"On a stamping drawing, the allowance is the length of material needed to form each:","bend",["hole","layer","title"],"Bend allowance accounts for bending.")
H('400.d.7.K',3,"Numerical-control drawings give dimensions from a:","zero point (datum)",["moving point","random point","sign"],"NC drawings use a reference origin.")
H('400.d.7.K',4,"Dimensioning for CNC from a single datum, called ordinate or baseline dimensioning, avoids the buildup of:","tolerance errors",["colors","layers","lines"],"Baseline dimensioning limits accumulation.")
H('400.d.7.L',3,"A parts list on a drawing includes the item number, the description, and the:","quantity",["owner","date of birth","paint"],"Parts lists show quantity.")
H('400.d.7.L',4,"A material specification such as ASTM A36 on a drawing tells the manufacturer which:","grade of steel to use",["color to paint","layer to use","shift to work"],"Specifications identify material grade.")
H('400.d.7.M',3,"A geometric tolerance is shown in a:","feature control frame",["title block","parts list","legend"],"Feature control frames hold GD&T.")
H('400.d.7.M',4,"A flatness tolerance on a machined surface controls how much the surface may:","vary from a perfect plane",["change color","shrink","move"],"Flatness limits deviation.")
H('400.d.8.A',3,"A floor plan is a view looking down at a building after it has been cut at about:","four feet above the floor",["ground level","the roof","the footing"],"Plans are cut at window height.")
H('400.d.8.A',4,"A floor plan shows walls, doors, windows, and also the:","room names and dimensions",["roof shingles","exterior colors","tax value"],"Plans label rooms and sizes.")
H('400.d.8.B',3,"A site plan shows the building location on the:","lot",["roof","wall","floor"],"Site plans show the building on the lot.")
H('400.d.8.B',4,"A site plan includes property lines, setbacks, and the:","driveway and north arrow",["paint","door schedule","furniture"],"Site plans show access and orientation.")
H('400.d.8.C',3,"An elevation drawing shows a building as seen from the:","side, front, or rear",["top only","inside floor","footing"],"Elevations are side views.")
H('400.d.8.C',4,"Interior elevations show features such as cabinets and wall finishes on the:","inside walls of a room",["roof","sidewalk","foundation"],"Interior elevations show walls.")
H('400.d.8.D',3,"A gable roof has two sloping sides that meet at a:","ridge",["valley","eave","soffit"],"Gables meet at the ridge.")
H('400.d.8.D',4,"Roof pitch is expressed as the rise for every 12 inches of:","run",["length","area","height"],"Pitch is rise over run.")
H('400.d.8.E',3,"A door schedule is a table listing each door's number, size, and:","type",["owner","paint cost","weather"],"Schedules list door information.")
H('400.d.8.E',4,"Window schedules use symbols on the plan, such as a letter in a circle, that refer to the table's:","window marks",["room names","roof lines","fonts"],"Marks link plan to schedule.")
H('400.d.8.F',3,"A wall section shows the construction of a wall from the foundation to the:","roof",["sidewalk","street","garden"],"Wall sections run foundation to roof.")
H('400.d.8.F',4,"A building section is cut through the structure to show the interior heights and the:","structural materials",["owner","paint","furniture"],"Sections reveal assembly.")
H('400.d.8.G',3,"The overall site plan includes features outside the building, such as:","utilities and landscaping",["wall studs","window glass","interior doors"],"Site plans show site features.")
H('400.d.8.G',4,"Contour lines on a site plan show changes in the land's:","elevation",["color","owner","size"],"Contours show elevation.")
H('400.d.8.H',3,"A plot plan is a drawing of a lot showing the building and the:","property boundaries",["door schedule","paint colors","roof truss"],"Plot plans show boundaries.")
H('400.d.8.H',4,"Setbacks shown on a plot plan are the minimum distances a building must stay from the:","property lines",["trees","utilities","neighbors' cars"],"Setbacks are set by code.")
H('400.d.8.I',3,"Plans are reviewed and revised during the design process to meet client needs and:","building codes",["fashion","music","weather"],"Revisions satisfy requirements.")
H('400.d.8.I',4,"Keeping a revision log on drawings helps the team to know what changed and:","when it changed",["why the sky is blue","the weather","who won"],"Revision logs track changes.")
H('400.d.8.J',3,"When a client changes a design request late in the process, a flexible designer will:","adapt the plans to the new request",["refuse","quit","ignore it"],"Flexibility means adapting.")
H('400.d.8.J',4,"Being adaptable during design includes accepting feedback and being willing to:","revise the design",["stop working","hide the plans","blame others"],"Adaptability supports improvement.")
H('400.d.8.K',3,"A basic project materials list shows each material, its size, and its:","quantity",["owner","color of the sky","age"],"Materials lists show quantity.")
H('400.d.8.K',4,"A materials list is used to estimate the:","cost of a project",["time of day","weather","street names"],"Lists support cost estimates.")

H('399.d.10.G',4,"In a drafting set, the sheet that tabulates every opening's size, type, and quantity is the:","door and window schedule",["site plan","roof plan","title sheet"],"Schedules tabulate openings.")

